export function outputScale(data,normalize=false,targetDb=-1){let peak=0;for(const ch of data)for(const v of ch)peak=Math.max(peak,Math.abs(v));return{peak,scale:normalize&&peak>0?10**(targetDb/20)/peak:peak>1?1/peak:1};}
export function pcmWav(data,rate,bits=16,scale=1){const channels=data.length,n=data[0].length,float=bits===32,bytes=bits/8,ab=new ArrayBuffer(44+n*channels*bytes),view=new DataView(ab),str=(p,s)=>{for(let i=0;i<s.length;i++)view.setUint8(p+i,s.charCodeAt(i));};str(0,'RIFF');view.setUint32(4,ab.byteLength-8,true);str(8,'WAVE');str(12,'fmt ');view.setUint32(16,16,true);view.setUint16(20,float?3:1,true);view.setUint16(22,channels,true);view.setUint32(24,rate,true);view.setUint32(28,rate*channels*bytes,true);view.setUint16(32,channels*bytes,true);view.setUint16(34,bits,true);str(36,'data');view.setUint32(40,n*channels*bytes,true);for(let i=0,p=44;i<n;i++)for(let c=0;c<channels;c++,p+=bytes){const v=Math.max(-1,Math.min(1,data[c][i]*scale));if(float)view.setFloat32(p,v,true);else if(bits===24){const v24=Math.round(v*(v<0?8388608:8388607));view.setUint8(p,v24&255);view.setUint8(p+1,(v24>>8)&255);view.setUint8(p+2,(v24>>16)&255);}else view.setInt16(p,Math.round(v*(v<0?32768:32767)),true);}return ab;}
